import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"ATLAS Terminal","description":"ATLAS browser terminal with ANSI colors, optional SSH, Oh My Posh themes and a server-served Nerd Font.","frontmatter":{"title":"ATLAS Terminal","description":"ATLAS browser terminal with ANSI colors, optional SSH, Oh My Posh themes and a server-served Nerd Font."},"headers":[],"relativePath":"en/projects/atlas-plugins/terminal.md","filePath":"en/projects/atlas-plugins/terminal.md","lastUpdated":1792861636000}'),r={name:"en/projects/atlas-plugins/terminal.md"};function s(i,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="atlas-terminal" tabindex="-1">ATLAS Terminal <a class="header-anchor" href="#atlas-terminal" aria-label="Permalink to &quot;ATLAS Terminal&quot;">​</a></h1><p>ATLAS Terminal is a standalone plugin repository for an authenticated browser terminal. It provides ANSI colors, an adjustable font size, selectable Oh My Posh themes and an optional SSH connection to a server-configured target.</p><p>The interface is available in German, English and French. The language choice is saved in the browser and can also be passed in the <code>language</code> URL parameter.</p><h2 id="repository-and-installation" tabindex="-1">Repository and Installation <a class="header-anchor" href="#repository-and-installation" aria-label="Permalink to &quot;Repository and Installation&quot;">​</a></h2><ul><li>GitHub: <a href="https://github.com/rockbaer2007/atlas-terminal-plugin" target="_blank" rel="noreferrer">rockbaer2007/atlas-terminal-plugin</a></li><li>Install page: <a href="https://rockbaer2007.github.io/atlas-terminal-plugin/install.html" target="_blank" rel="noreferrer">Add ATLAS Terminal</a></li><li>Repository manifest: <a href="https://raw.githubusercontent.com/rockbaer2007/atlas-terminal-plugin/main/repository.json" target="_blank" rel="noreferrer">repository.json</a></li><li>Plugin version: <code>0.1.10</code></li></ul><p>In ATLAS Administration, open <strong>Plugins → Add repository</strong>, choose <strong>Plugin</strong>, and enter the manifest URL. Review the repository and install the plugin package. The ATLAS host must provide a compatible Terminal backend.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>browser terminal with ANSI colors</li><li>locally adjustable font size</li><li>selectable Oh My Posh themes for local Bash sessions</li><li>Meslo LGM Nerd Font is served by Home Assistant; clients do not need a local font installation</li><li>optional SSH target with a server-configured host, user, key and <code>known_hosts</code></li><li>host-key verification stays enabled; the browser cannot select an arbitrary SSH target</li><li>independently versioned frontend in the plugin repository</li><li>collapsible token settings: they close on connect and reopen after disconnecting or when the session ends</li><li>local shell sessions start at filesystem root <code>/</code> inside the ATLAS container instead of <code>/app</code>; SSH keeps the target server&#39;s default directory</li></ul><h2 id="setting-up-the-nerd-font" tabindex="-1">Setting up the Nerd Font <a class="header-anchor" href="#setting-up-the-nerd-font" aria-label="Permalink to &quot;Setting up the Nerd Font&quot;">​</a></h2><p>Place <code>MesloLGMNerdFontMono-Regular.ttf</code> and <code>MesloLGMNerdFontMono-Bold.ttf</code> in <code>/config/www/fonts/</code> or directly in <code>/config/www/</code>. Home Assistant serves them at <code>/local/fonts/</code> or <code>/local/</code>, and the terminal loads the font files from there.</p><h2 id="requirements-and-security" tabindex="-1">Requirements and Security <a class="header-anchor" href="#requirements-and-security" aria-label="Permalink to &quot;Requirements and Security&quot;">​</a></h2><p>The repository contains the plugin frontend, but it is <strong>not a standalone SSH server or a Home Assistant add-on</strong>. The ATLAS host provides the shell, Supervisor and WebSocket functions. Since plugin <code>0.1.10</code>, catalog, package and manifest declare App/runtime <code>&gt;=0.1.215 &lt;0.2.0</code>, host <code>administration-local</code> and Home Assistant <code>&gt;=2026.8</code>. The previous <code>&gt;=0.2.0-alpha.79</code> referred to a framework version and was incorrect in <code>compatibility.atlas</code>. App and framework have separate version identities.</p><p>Existing shared Terminal descriptors may retain the old requirement. Back up HA and shared plugin state first, then correct only the proven version-identity error with a current revision check. Preserve activation, other requirements and all other entries. Refreshing the repository alone does not change saved state. Existing recovery snapshots keep their requirements; do not rewrite them without review or bypass compatibility checks. Correcting metadata migrates neither tokens nor plugin data. Loading the Meslo font requires App/Add-on <code>0.1.214</code>; the root working directory and collapsible token settings require <code>0.1.215</code> or newer.</p><p>The terminal is disabled by default. Enable it only after configuring a strong, random access token of at least 32 URL-safe characters on the ATLAS host. The local shell runs with the permissions of the ATLAS process. In Home Assistant App/Add-on mode, Supervisor permissions may also enable administrative <code>ha</code> commands. Treat terminal access as administrative access.</p><p>The access token stays in local browser storage and is sent during connection setup through the WebSocket subprotocol, not in a URL. The token settings collapse when a session connects and reopen after disconnecting or when the session ends. They are open on first load if no token is saved. Scripts from the same website can access this storage. Use the terminal only in a trusted browser profile.</p><h2 id="status-and-license" tabindex="-1">Status and License <a class="header-anchor" href="#status-and-license" aria-label="Permalink to &quot;Status and License&quot;">​</a></h2><p>The plugin is listed as <strong>experimental</strong> because it requires a compatible ATLAS backend. It is licensed under <a href="https://github.com/rockbaer2007/atlas-terminal-plugin/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a>.</p>',17)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
